// ── Build Query Window ───────────────────────────────────────────────────────
// FDA publishes the Enforcement Report weekly, so a daily poll uses a 7-day
// look-back. Re-seen events are harmless: the database de-dup key blocks any
// second pitch for the same event x SKU.
const LOOKBACK_DAYS = 7;

const now = new Date();
const from = new Date(now.getTime() - LOOKBACK_DAYS * 24 * 60 * 60 * 1000);
const yyyymmdd = (d) => d.toISOString().slice(0, 10).replace(/-/g, '');

return [{
  json: {
    run_id: 'RUN-' + now.toISOString().replace(/[-:T]/g, '').slice(0, 14),
    run_started_at: now.toISOString(),
    lookback_days: LOOKBACK_DAYS,
    from_date: yyyymmdd(from),
    to_date: yyyymmdd(now),
    window_start_iso: from.toISOString(),
    // openFDA Lucene-style query; n8n URL-encodes spaces as "+"
    enforcement_search: `report_date:[${yyyymmdd(from)} TO ${yyyymmdd(now)}]`,
    shortage_search: 'status:"Current"',
    // Manual test runs use pinned demo data whose dates are fixed, so the
    // shortage date filter is relaxed for 'test' executions only.
    is_test_run: $execution.mode === 'test',
  },
}];

parameters.query:
SELECT array_agg(DISTINCT lower(molecule_name) ORDER BY lower(molecule_name)) AS molecules
FROM internal_sku_inventory
WHERE is_active;

