// ── Normalize & Pre-Filter Events ────────────────────────────────────────────
// 1. Flattens openFDA enforcement + shortage results into one event list.
// 2. Deterministic pre-filter BEFORE the LLM: Class I/II, ongoing, inside the
//    window, and the product must mention a molecule in our active portfolio.
//    This keeps LLM spend proportional to commercial relevance.
const MAX_EVENTS_PER_RUN = 40;            // LLM cost guardrail
const RELEVANT_CLASSES = ['Class I', 'Class II'];

const win = $('Build Query Window').first().json;
const portfolio = ($('Load Portfolio Molecules').first().json.molecules || []).filter(Boolean);
const enf = $('OpenFDA Enforcement').first().json || {};
const sho = $('OpenFDA Shortages').first().json || {};

const escRe = (s) => s.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
const stems = [...new Set(portfolio.map((m) => String(m).toLowerCase().split(/\s+/)[0]))];
const portfolioRe = stems.length ? new RegExp(`\\b(${stems.map(escRe).join('|')})\\b`, 'i') : null;
const inPortfolio = (text) => (portfolioRe ? portfolioRe.test(text || '') : false);

// openFDA shortage dates are MM/DD/YYYY
const parseUsDate = (s) => {
  const m = /^(\d{2})\/(\d{2})\/(\d{4})$/.exec(String(s || '').trim());
  return m ? new Date(Date.UTC(+m[3], +m[1] - 1, +m[2])) : null;
};
const windowStart = new Date(win.window_start_iso);

const events = new Map();
let seen = 0;

for (const r of enf.results || []) {
  seen++;
  if (!RELEVANT_CLASSES.includes(r.classification)) continue;
  if (r.status && r.status !== 'Ongoing') continue;
  const generic = ((r.openfda || {}).generic_name || []).join(' ');
  if (!inPortfolio(`${r.product_description} ${generic}`)) continue;
  events.set(r.recall_number, {
    source_type: 'FDA_ENFORCEMENT',
    source_event_id: r.recall_number,
    recall_classification: r.classification,
    recalling_firm: r.recalling_firm || '',
    reason: r.reason_for_recall || '',
    report_date: r.report_date || '',
    llm_input_text: [
      `SOURCE: FDA_ENFORCEMENT | RECALL_NUMBER: ${r.recall_number} | CLASS: ${r.classification}`,
      `RECALLING_FIRM: ${r.recalling_firm || ''}`,
      `PRODUCT_DESCRIPTION: ${r.product_description || ''}`,
      `CODE_INFO: ${r.code_info || ''}`,
      `REASON_FOR_RECALL: ${r.reason_for_recall || ''}`,
      `DISTRIBUTION_PATTERN: ${r.distribution_pattern || ''}`,
    ].join('\n'),
  });
}

for (const r of sho.results || []) {
  seen++;
  const updated = parseUsDate(r.update_date) || parseUsDate(r.initial_posting_date);
  if (!win.is_test_run && updated && updated < windowStart) continue;
  const generic = ((r.openfda || {}).generic_name || []).join(' ');
  if (!inPortfolio(`${r.generic_name} ${r.presentation} ${generic}`)) continue;
  const id = `SHORTAGE:${r.package_ndc}:${r.update_date || r.initial_posting_date}`;
  events.set(id, {
    source_type: 'FDA_SHORTAGE',
    source_event_id: id,
    recall_classification: null,
    recalling_firm: r.company_name || '',
    reason: r.shortage_reason || r.availability || '',
    report_date: r.update_date || '',
    llm_input_text: [
      `SOURCE: FDA_SHORTAGE | STATUS: ${r.status || ''} | AVAILABILITY: ${r.availability || ''}`,
      `COMPANY: ${r.company_name || ''}`,
      `GENERIC_NAME: ${r.generic_name || ''}`,
      `PRESENTATION: ${r.presentation || ''}`,
      `PACKAGE_NDC: ${r.package_ndc || ''}`,
      `SHORTAGE_REASON: ${r.shortage_reason || ''}`,
      'DISTRIBUTION_PATTERN: FDA national shortage list (nationwide)',
    ].join('\n'),
  });
}

const out = [...events.values()].slice(0, MAX_EVENTS_PER_RUN).map((e) => ({
  json: { ...e, run_id: win.run_id },
}));

console.log(`openFDA records scanned: ${seen} | portfolio-relevant events sent to LLM: ${out.length}`);
return out; // zero items => the workflow ends quietly (nothing relevant today)

