{
  "type": "object",
  "properties": {
    "products": {
      "type": "array",
      "description": "One entry per distinct NDC printed in the FDA record",
      "items": {
        "type": "object",
        "properties": {
          "generic_name": { "type": "string", "description": "Active ingredient, lower case, salt form kept (e.g. albuterol sulfate)" },
