          "ndc_raw": { "type": "string", "description": "NDC exactly as printed, empty string if none" },
          "ndc_11": { "type": "string", "description": "HIPAA 5-4-2 with hyphens, empty string if ambiguous or missing" },
          "ndc_source_format": {
            "type": "string",
            "enum": ["4-4-2", "5-3-2", "5-4-1", "5-4-2", "AMBIGUOUS_UNHYPHENATED", "NOT_FOUND"]
          }
        },
        "required": ["generic_name", "strength_norm", "dosage_form", "ndc_raw", "ndc_11", "ndc_source_format"]
      }
    },
    "distribution": {
      "type": "object",
      "properties": {
        "nationwide": { "type": "boolean" },
        "us_state_codes": {
          "type": "array",
          "items": { "type": "string", "description": "Two-letter USPS code, upper case" }
        }
      },
      "required": ["nationwide", "us_state_codes"]
    },
    "supply_impact_summary": { "type": "string", "description": "One neutral factual sentence, max 200 characters" }
  },
  "required": ["products", "distribution", "supply_impact_summary"]
}

