// ── NDC & State QA Gate (deterministic, post-LLM) ───────────────────────────
// The LLM proposes; this node decides. Every extracted product must pass:
//   G1 Grounding   – the raw NDC string must appear verbatim in the FDA text
//   G2 NDC rebuild – NDC-11 is recomputed with rules (not trusted from the LLM)
//                    and must match ^\d{5}-\d{4}-\d{2}$ (HIPAA 5-4-2)
//   G3 States      – only valid USPS codes survive; at least one required
//   G4 Product     – molecule present; strength in a normalized pattern
// Failures are routed to QA quarantine (logged), never to Sales.
const NDC_11_RE = /^\d{5}-\d{4}-\d{2}$/;
const STRENGTH_RE = /^\d+(\.\d+)?(MG|MCG|G|MEQ|UNITS?|%)(\/(\d+(\.\d+)?)?(ML|L|G|ACTUATION|DOSE))?$/;
const US_51 = ['AL','AK','AZ','AR','CA','CO','CT','DE','DC','FL','GA','HI','ID','IL','IN','IA','KS',
  'KY','LA','ME','MD','MA','MI','MN','MS','MO','MT','NE','NV','NH','NJ','NM','NY','NC','ND','OH',
  'OK','OR','PA','RI','SC','SD','TN','TX','UT','VT','VA','WA','WV','WI','WY'];
const VALID_STATES = new Set([...US_51, 'PR']);

// 10-digit NDC (4-4-2 | 5-3-2 | 5-4-1) -> 11-digit 5-4-2 by zero-padding the short segment
function normalizeNdc(raw) {
  if (!raw) return { ndc11: null, format: 'NOT_FOUND' };
  const s = String(raw).toUpperCase()
    .replace(/[‐-―−]/g, '-')       // unicode dashes -> hyphen
    .replace(/^\s*NDC\s*[:#]?\s*/, '')
    .replace(/\s+/g, '');
  const parts = s.split('-');
  if (parts.length === 3 && parts.every((p) => /^\d+$/.test(p))) {
    const [a, b, c] = parts;
    switch (`${a.length}-${b.length}-${c.length}`) {
      case '4-4-2': return { ndc11: `0${a}-${b}-${c}`, format: '4-4-2' };
      case '5-3-2': return { ndc11: `${a}-0${b}-${c}`, format: '5-3-2' };
      case '5-4-1': return { ndc11: `${a}-${b}-0${c}`, format: '5-4-1' };
      case '5-4-2': return { ndc11: `${a}-${b}-${c}`, format: '5-4-2' };
      default:      return { ndc11: null, format: 'INVALID_SEGMENTS' };
    }
  }
  const digits = s.replace(/\D/g, '');
  if (digits.length === 11) {
    return { ndc11: `${digits.slice(0, 5)}-${digits.slice(5, 9)}-${digits.slice(9)}`, format: '11_UNHYPHENATED' };
  }
  // A bare 10-digit NDC cannot be split without knowing its configuration
  if (digits.length === 10) return { ndc11: null, format: 'AMBIGUOUS_UNHYPHENATED' };
  return { ndc11: null, format: 'INVALID' };
}

const normStrength = (s) => String(s || '').toUpperCase()
  .replace(/\s+/g, '')
  .replace(/[µμΜ]G/g, 'MCG')
  .replace(/(^|[^A-Z])UG/g, '$1MCG');
const compact = (s) => String(s || '').toUpperCase().replace(/[\s‐-―−-]/g, '');

const srcItems = $('Normalize & Pre-Filter Events').all();
const out = [];

$input.all().forEach((item, i) => {
  let src;
  try { src = $('Normalize & Pre-Filter Events').itemMatching(i).json; }
  catch (e) { src = srcItems[i].json; }

  const x = item.json.output || {};
  const dist = x.distribution || {};
  const base = {
    run_id: src.run_id,
    source_type: src.source_type,
    source_event_id: src.source_event_id,
    recall_classification: src.recall_classification,
    recalling_firm: src.recalling_firm,
    reason: src.reason,
  };

  // ── G3: states ────────────────────────────────────────────────────────────
  const rawStates = (dist.us_state_codes || []).map((c) => String(c).trim().toUpperCase());
  const droppedStates = rawStates.filter((c) => !VALID_STATES.has(c));
  const nationwide = dist.nationwide === true || src.source_type === 'FDA_SHORTAGE';
  const states = nationwide ? [...US_51, 'PR'] : [...new Set(rawStates.filter((c) => VALID_STATES.has(c)))];

  const products = Array.isArray(x.products) ? x.products : [];
  const quarantine = (reasons, p = {}) => {
    const ndcRaw = p.ndc_raw || 'NO-NDC';
    out.push({ json: {
      ...base, qa_passed: false, qa_notes: reasons.join('; '),
      molecule_name: (p.generic_name || '').toLowerCase() || null,
      ndc_raw: p.ndc_raw || null,
      log_record: {
        dedup_key: `${src.source_event_id}|${ndcRaw}|QA`,
        run_id: src.run_id, source_type: src.source_type, source_event_id: src.source_event_id,
        recall_classification: src.recall_classification, recalling_firm: src.recalling_firm,
        external_ndc_11: null, molecule_name: (p.generic_name || '').toLowerCase() || null,
        strength_norm: normStrength(p.strength_norm) || null,
        affected_states: states.length ? states : null,
        decision_status: 'QA_QUARANTINE', qa_notes: reasons.join('; '),
      },
    } });
  };

  if (item.json.error || !item.json.output) { quarantine(['LLM_EXTRACTION_FAILED']); return; }
  if (!products.length) { quarantine(['NO_PRODUCT_EXTRACTED']); return; }

  // Group passing products by molecule + strength (one commercial signal each)
  const passed = new Map();

  for (const p of products) {
    const reasons = [];
    const notes = [];

    // ── G1 + G2: NDC ────────────────────────────────────────────────────────
    const det = normalizeNdc(p.ndc_raw);
    if (!p.ndc_raw) reasons.push('NDC_NOT_FOUND');
    else if (!compact(src.llm_input_text).includes(compact(p.ndc_raw))) reasons.push('NDC_NOT_GROUNDED_IN_SOURCE');
    if (p.ndc_raw && !det.ndc11) reasons.push(`NDC_UNRESOLVABLE:${det.format}`);
    if (det.ndc11 && !NDC_11_RE.test(det.ndc11)) reasons.push('NDC_FAILED_542_REGEX');
    const llmNdc = String(p.ndc_11 || '').trim();
    if (det.ndc11 && llmNdc !== det.ndc11) notes.push(`LLM_NDC_CORRECTED:${llmNdc || 'blank'}->${det.ndc11}`);

    // ── G4: product attributes ──────────────────────────────────────────────
    const molecule = String(p.generic_name || '').trim().toLowerCase();
    const strength = normStrength(p.strength_norm);
    if (!/^[a-z0-9][a-z0-9 \-]+$/.test(molecule)) reasons.push('MOLECULE_INVALID');
    if (!STRENGTH_RE.test(strength)) reasons.push(`STRENGTH_UNPARSEABLE:${strength || 'blank'}`);

    // ── G3: geography ───────────────────────────────────────────────────────
    if (!states.length) reasons.push('NO_VALID_US_STATES');
    if (droppedStates.length) notes.push(`DROPPED_INVALID_STATES:${droppedStates.join(',')}`);

    if (reasons.length) { quarantine([...reasons, ...notes], p); continue; }

    const key = `${molecule}|${strength}`;
    if (!passed.has(key)) {
      passed.set(key, { molecule, strength, dosage_form: p.dosage_form || '', ndcs: [], notes: [] });
    }
    const g = passed.get(key);
    g.ndcs.push(det.ndc11);
    g.notes.push(...notes);
  }

  for (const g of passed.values()) {
    out.push({ json: {
      ...base,
      qa_passed: true,
      qa_key: `${src.source_event_id}|${g.molecule}|${g.strength}`,
      molecule_name: g.molecule,
      strength_norm: g.strength,
      dosage_form: g.dosage_form,
      external_ndc_11: g.ndcs[0],
      external_ndcs: [...new Set(g.ndcs)].join(', '),
      nationwide,
      affected_states: states,
      affected_states_pipe: states.join('|'),
      qa_notes: [...new Set(g.notes)].join('; ') || null,
      supply_impact_summary: x.supply_impact_summary || '',
    } });
  }
});

return out;

// ── BA Spot-Buy Sizing (deterministic commercial logic — no LLM) ────────────
// Per matched SKU:
//   fts_buffer_units     = CEIL(committed_units × 15%)
//   protected_units      = committed_units + fts_buffer_units
//   spot_eligible_units  = MAX(0, on_hand_units − protected_units)
//   addressable_units    = MIN(spot_eligible_units, target_monthly_units × months_of_cover)
//   spot_price_per_unit  = ROUND(WAC × (1 − 12%), 2)
//   net_spot_revenue_usd = addressable_units × spot_price_per_unit
// Decision: ≥ $50k → PITCH_DISPATCHED | eligible = 0 → FTS_PROTECTED_NO_CAPACITY | else BELOW_THRESHOLD
const CFG = {
  SPOT_DISCOUNT_PCT: 0.12,     // spot price = WAC − 12% (below WAC by design: no shortage price-gouging)
  FTS_BUFFER_PCT: 0.15,        // safety stock held above GPO-committed volume
  MONTHS_OF_COVER: 1,          // size the pitch to one month of target-account demand
  MIN_NET_REVENUE_USD: 50000,  // keep in sync with the "Net Revenue ≥ $50k?" If node
};

const qaByKey = new Map($('NDC & State QA Gate').all().map((i) => [i.json.qa_key, i.json]));
const round2 = (n) => Math.round((n + Number.EPSILON) * 100) / 100;
const int = (v) => Math.trunc(Number(v) || 0);                      // pg returns BIGINT as text
const money = (n) => '$' + Number(n).toFixed(2).replace(/\B(?=(\d{3})+(?!\d))/g, ',');
const qty = (n) => String(n).replace(/\B(?=(\d{3})+(?!\d))/g, ',');

return $input.all().map((item) => {
  const m = item.json;
  const ev = qaByKey.get(m.qa_key) || {};

  const onHand = int(m.on_hand_units);
  const committed = int(m.committed_units);
  const wac = Number(m.wac_per_unit);                              // pg returns NUMERIC as text
  const targetMonthly = int(m.target_monthly_units);

  const ftsBuffer = Math.ceil(committed * CFG.FTS_BUFFER_PCT);
  const protectedUnits = committed + ftsBuffer;
  const spotEligible = Math.max(0, onHand - protectedUnits);
  const demandCap = Math.round(targetMonthly * CFG.MONTHS_OF_COVER);
  const addressable = Math.min(spotEligible, demandCap);
  const spotPrice = round2(wac * (1 - CFG.SPOT_DISCOUNT_PCT));
  const netRevenue = round2(addressable * spotPrice);

  const meetsThreshold = netRevenue >= CFG.MIN_NET_REVENUE_USD;
  const decision = meetsThreshold ? 'PITCH_DISPATCHED'
    : spotEligible === 0 ? 'FTS_PROTECTED_NO_CAPACITY'
    : 'BELOW_THRESHOLD';

  const footprint = ev.nationwide ? 'Nationwide' : (ev.affected_states || []).join(', ');
  const trigger = ev.source_type === 'FDA_SHORTAGE'
    ? `FDA Drug Shortage list · ${ev.recalling_firm}`
    : `FDA Enforcement ${ev.source_event_id} · ${ev.recall_classification} · ${ev.recalling_firm}`;
  const unit = String(m.sell_unit || 'unit').toLowerCase();
  const title = String(m.molecule_name).replace(/\b[a-z]/g, (c) => c.toUpperCase());

  const slack_message = [
    `:rotating_light: *Spot-Buy Opportunity: ${title} ${m.strength_norm}*`,
    `*Trigger:* ${trigger}`,
    `*Reason:* ${ev.reason || 'n/a'}`,
    `*Footprint:* ${footprint}`,
    '',
    `*Our supply: ${m.sku_id}* (NDC ${m.our_ndc_11}) ${m.sku_description}`,
    `• On hand ${qty(onHand)} · GPO-committed ${qty(committed)} · FTS buffer (15%) ${qty(ftsBuffer)}`,
    `• Spot-eligible after FTS protection: ${qty(spotEligible)} ${unit}s`,
    `• Addressable (1 month of target demand): ${qty(addressable)} ${unit}s`,
    '',
    `*Commercials:* spot ${money(spotPrice)}/${unit} (WAC ${money(wac)} − 12%)`,
    `*Est. net spot revenue: ${money(netRevenue)}*`,
    '',
    `*Target accounts (${int(m.target_account_count)}):* ${m.target_accounts || 'none in footprint'}`,
    `*KAM owners:* ${m.kam_owners || 'unassigned'}`,
    '_Next step: Pricing & Contracts approval, then outreach with the MLR-approved shortage-response template only. Reference the public FDA record; make no other claims about the competitor._',
  ].join('\n');

  return {
    json: {
      ...m,
      source_type: ev.source_type,
      recall_classification: ev.recall_classification,
      recalling_firm: ev.recalling_firm,
      external_ndc_11: ev.external_ndc_11,
      affected_states: ev.affected_states,
      fts_buffer_units: ftsBuffer,
      protected_units: protectedUnits,
      spot_eligible_units: spotEligible,
      addressable_units: addressable,
      spot_price_per_unit: spotPrice,
      net_spot_revenue_usd: netRevenue,
      meets_threshold: meetsThreshold,
      decision_status: decision,
      slack_message,
      log_record: {
        dedup_key: `${m.qa_key}|${m.sku_id}`,
        run_id: ev.run_id,
        source_type: ev.source_type,
        source_event_id: ev.source_event_id,
        recall_classification: ev.recall_classification,
        recalling_firm: ev.recalling_firm,
        external_ndc_11: ev.external_ndc_11,
        molecule_name: m.molecule_name,
        strength_norm: m.strength_norm,
        affected_states: ev.affected_states,
        sku_id: m.sku_id,
        on_hand_units: onHand,
        committed_units: committed,
        fts_buffer_units: ftsBuffer,
        spot_eligible_units: spotEligible,
        target_monthly_units: targetMonthly,
        addressable_units: addressable,
        wac_per_unit: wac,
        spot_price_per_unit: spotPrice,
        net_spot_revenue_usd: netRevenue,
        target_account_count: int(m.target_account_count),
        decision_status: decision,
        qa_notes: ev.qa_notes || null,
      },
    },
  };
});
